"""Master-key file parsing and decryption.

A master-key file holds up to four sections (master key, backup key, credential
history, domain key). Only the master-key section is decrypted here; it yields the
64-byte key that unprotects blobs created by that key's GUID.
"""
import hmac
import os
import struct

from . import primitives as P


def master_key_guid(mk_file):
    """The GUID a master-key file declares (its own file name, stored as UTF-16LE)."""
    return mk_file[12:84].decode('utf-16-le').strip('\x00')


def decrypt_master_key(mk_file, candidates):
    """The 64-byte master key, using the first pre-key candidate that verifies.

    ``candidates`` are the SHA-1 pre-keys (e.g. the DPAPI_SYSTEM user/machine keys for
    SYSTEM master keys, or ``SHA1(password)`` derived pre-keys for user master keys).
    Returns ``None`` if none verify.
    """
    mk_len = struct.unpack('<Q', mk_file[96:104])[0]
    mk = mk_file[128:128 + mk_len]
    salt = mk[4:20]
    rounds = struct.unpack('<L', mk[20:24])[0]
    alg_hash = struct.unpack('<L', mk[24:28])[0]
    alg_crypt = struct.unpack('<L', mk[28:32])[0]
    ciphertext = mk[32:]
    key_len, iv_len = P.cipher_sizes(alg_crypt)
    hname = P.hash_name(alg_hash)
    hlen = P.hash_len(alg_hash)
    for pre_key in candidates:
        derived = P.dpapi_kdf(pre_key, salt, key_len + iv_len, rounds, alg_hash)
        clear = P.cbc_decrypt(alg_crypt, derived[:key_len], derived[key_len:key_len + iv_len],
                              ciphertext)
        hmac_salt = clear[:16]
        key = clear[-64:]
        stored = clear[16:16 + hlen]
        tmp = hmac.new(pre_key, hmac_salt, hname).digest()
        if hmac.new(tmp, key, hname).digest() == stored:
            return key
    return None


class MasterKeyPool:
    """A GUID-indexed set of master-key files from one or more Protect directories."""

    def __init__(self):
        self._files = {}   # guid -> raw bytes
        self._keys = {}     # guid -> decrypted 64-byte key

    def load_directory(self, directory):
        """Load every master-key file (name is a GUID) found directly in ``directory``."""
        if not os.path.isdir(directory):
            return
        for name in os.listdir(directory):
            path = os.path.join(directory, name)
            if not os.path.isfile(path):
                continue
            if len(name) != 36 or name.count('-') != 4:
                continue
            with open(path, 'rb') as handle:
                self._files[name.lower()] = handle.read()

    def add_file(self, path):
        with open(path, 'rb') as handle:
            data = handle.read()
        self._files[master_key_guid(data).lower()] = data

    def guids(self):
        return list(self._files)

    def decrypt_all(self, candidates):
        """Decrypt every loaded master key with ``candidates``; return count decrypted."""
        for guid, raw in self._files.items():
            if guid in self._keys:
                continue
            key = decrypt_master_key(raw, candidates)
            if key is not None:
                self._keys[guid] = key
        return len(self._keys)

    def get_key(self, guid):
        """The decrypted key for a GUID, or ``None`` if absent or not yet decrypted."""
        return self._keys.get(guid.lower())
